def create_variables(solver, N, M):
    """Create decision variables."""
    assign = [[solver.BoolVar(f"assign_{i}_{k}") for k in range(M)] for i in range(N)]

    seq = [[[solver.BoolVar(f"seq_{i}_{j}_{k}") for k in range(M)] for j in range(N)] for i in range(N)]

    is_source = [[solver.BoolVar(f"source_{i}_{k}") for k in range(M)] for i in range(N)]

    return assign, seq, is_source

def add_constraints(solver, N, M, start, end, duration, travel, max_duration, assign, seq, is_source):
    """Add all constraints to the model."""
    INF = solver.infinity()
    large_M = 10000

    for i in range(N):
        solver.Add(sum(assign[i][k] for k in range(M)) == 1)

    for k in range(M):
        solver.Add(sum(assign[i][k] * duration[i] for i in range(N)) <= max_duration)

    for i in range(N):
        for j in range(N):
            for k in range(M):
                solver.Add(seq[i][j][k] <= assign[i][k])
                solver.Add(seq[i][j][k] <= assign[j][k])
                if travel[i][j] >= 5000:
                    solver.Add(seq[i][j][k] == 0)

    for i in range(N):
        for k in range(M):
            solver.Add(seq[i][i][k] == 0)

    for j in range(N):
        for k in range(M):
            solver.Add(sum(seq[i][j][k] for i in range(N) if i != j) <= 1)

    for i in range(N):
        for k in range(M):
            solver.Add(sum(seq[i][j][k] for j in range(N) if j != i) <= 1)

    for j in range(N):
        for k in range(M):
            solver.Add(assign[j][k] == is_source[j][k] + sum(seq[i][j][k] for i in range(N) if i != j))

    for k in range(M):
        solver.Add(sum(is_source[i][k] for i in range(N)) <= 1)

    for i in range(N):
        for k in range(M):
            solver.Add(is_source[i][k] <= assign[i][k])

    for i in range(N):
        for j in range(N):
            if i != j:
                for k in range(M):
                    if travel[i][j] < 5000:
                        solver.Add(end[i] + travel[i][j] <= start[j] + (1 - seq[i][j][k]) * large_M)

    for i in range(N):
        for j in range(N):
            if i < j:
                overlap = (start[i] < end[j]) and (start[j] < end[i])

                if overlap:
                    for k in range(M):
                        solver.Add(assign[i][k] + assign[j][k] <= 1)

    return solver

def set_objective(solver, N, M, travel, seq):
    """Set the objective: minimize total travel time."""
    objective = solver.Objective()
    for i in range(N):
        for j in range(N):
            if i != j and travel[i][j] < 5000:
                for k in range(M):
                    objective.SetCoefficient(seq[i][j][k], travel[i][j])
    objective.SetMinimization()
    return solver

def solve_and_print_results(solver, N, M, assign, seq, is_source, travel):
    """Solve the model and print results."""
    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        total_travel = 0
        for i in range(N):
            for j in range(N):
                if i != j and travel[i][j] < 5000:
                    for k in range(M):
                        if seq[i][j][k].solution_value() > 0.5:
                            total_travel += travel[i][j]

        crews = []
        for k in range(M):
            crew_sequences = []
            for i in range(N):
                if assign[i][k].solution_value() > 0.5:
                    crew_sequences.append(i)
            if crew_sequences:
                source_seq = None
                for i in range(N):
                    if is_source[i][k].solution_value() > 0.5:
                        source_seq = i
                        break

                if source_seq is not None:
                    sequence_order = [source_seq]
                    current = source_seq

                    while True:
                        next_seq = None
                        for j in range(N):
                            if j != current and seq[current][j][k].solution_value() > 0.5:
                                next_seq = j
                                break

                        if next_seq is None:
                            break

                        sequence_order.append(next_seq)
                        current = next_seq
                    crews.append(sequence_order)
                else:
                    crews.append(sorted(crew_sequences))
            else:
                crews.append([])

        print(json.dumps({
            "crews": crews,
            "total_travel_time": total_travel
        }))
    elif status == pywraplp.Solver.FEASIBLE:
        print("Feasible solution found (may not be optimal)")
    else:
        print(f"No solution found. Solver status: {status}")

def main():
    """Main function to solve the scheduling problem."""
    solver = create_solver()

    N, M, start, end, duration, travel, max_duration = define_parameters()

    assign, seq, is_source = create_variables(solver, N, M)

    solver = add_constraints(solver, N, M, start, end, duration, travel, max_duration, assign, seq, is_source)

    solver = set_objective(solver, N, M, travel, seq)

    solve_and_print_results(solver, N, M, assign, seq, is_source, travel)

if __name__ == "__main__":
    main()
